                        note: string;
                        /**
                         * @description RECOVER_FROM_DRIVER only
                         * @example 2500000
                         */
                        recoveredAmountPaisa?: string | number;
                        /**
                         * Format: uuid
                         * @description ACCEPT_LOSS only (THEKEDAR): charge the loss to this sub-contract as a deduction
                         */
