                        /** Format: uuid */
                        projectId: string;
                        /** @enum {string} */
                        category: "TEA_WATER" | "TRANSPORT" | "UNLOADING" | "FUEL" | "SMALL_TOOLS" | "URGENT_MATERIAL" | "OWNER_PURCHASE" | "REPAIRS" | "OTHER";
                        /**
                         * @description Paisa as a string (2500000 = Rs 25,000)
                         * @example 2500000
                         */
                        amountPaisa: string | number;
